<?php $request=$page==='solicitar'; $delivery=$page==='adicionarepi'; $reasonKey=$request?'justificativa':($delivery?'motivo':'observacao'); ?>
<section class="card form-card"><h2><?= $request?'De qual equipamento você precisa?':($delivery?'Entrega para '.e($person['nome_completo']):'Reposição de equipamentos') ?></h2><p><?= $request?'Informe a quantidade e explique a necessidade. Sua solicitação será analisada pelo administrador.':($delivery?'A entrega registra a saída e desconta a quantidade disponível.':'Registre a necessidade de compra. O estoque será atualizado ao confirmar o recebimento em Compras.') ?></p>
<?php if(!$epis): ?><p class="empty">Não há EPIs cadastrados. Procure o administrador.</p><?php else: ?><form method="post" class="form-grid"><?= csrf() ?><?php if($delivery): ?><input type="hidden" name="id_funcionario" value="<?= (int)$person['id_funcionario'] ?>"><?php endif ?><label class="full">Equipamento<select name="id_epi" required><option value="">Selecione um EPI</option><?php foreach($epis as $epi): ?><option value="<?= (int)$epi['id_epi'] ?>" <?= (string)($_POST['id_epi']??$_GET['id_epi']??'')===(string)$epi['id_epi']?'selected':'' ?>><?= e($epi['nome_epi']) ?><?= $admin?' · '.(int)$epi['quantidade_estoque'].' em estoque':'' ?></option><?php endforeach ?></select></label><label>Quantidade<input type="number" name="quantidade" min="1" max="1000000" step="1" value="<?= e($_POST['quantidade']??1) ?>" required></label><label class="full"><?= $request?'Justificativa':($delivery?'Motivo da entrega':'Observação (opcional)') ?><textarea name="<?= e($reasonKey) ?>" rows="4" maxlength="<?= $request||$delivery?2000:255 ?>" <?= $request||$delivery?'required':'' ?>><?= e($_POST[$reasonKey]??($delivery?'Entrega de EPI':'')) ?></textarea></label><div class="form-actions full"><a class="button secondary" href="<?= $request?'minhassolicitacoes.php':($delivery?'informacoes.php?id='.(int)$person['id_funcionario']:'compras.php') ?>">Cancelar</a><button class="button"><?= $request?'Enviar solicitação':($delivery?'Registrar entrega':'Registrar pedido') ?> →</button></div></form><?php endif ?></section>
